import{_ as t,o as a,c as i,a2 as o}from"./chunks/framework.BXzK3EA4.js";const d=JSON.parse('{"title":"Security – Security Settings","description":"","frontmatter":{"title":"Security – Security Settings"},"headers":[],"relativePath":"operations-knowledge-base/presales-support/security-security-settings.md","filePath":"operations-knowledge-base/presales-support/security-security-settings.md","lastUpdated":1794292919000}'),n={name:"operations-knowledge-base/presales-support/security-security-settings.md"};function r(s,e,c,u,l,p){return a(),i("div",null,[...e[0]||(e[0]=[o('<h2 id="_1-overview" tabindex="-1">1. Overview <a class="header-anchor" href="#_1-overview" aria-label="Permalink to &quot;1. Overview&quot;">​</a></h2><p>Within the platform’s security settings, the “Two-Factor Authentication” feature is an important measure for improving account security.</p><p>By using a two-factor authentication mechanism, this feature adds an extra layer of protection to the login process, helping prevent unauthorized access and protect user accounts and related information.</p><h2 id="_2-access-path" tabindex="-1">2. Access Path <a class="header-anchor" href="#_2-access-path" aria-label="Permalink to &quot;2. Access Path&quot;">​</a></h2><p>Users can navigate to Top-right profile icon → Security to enter the Security Settings page, where the Two-Factor Authentication configuration section can be found.</p><h2 id="_3-feature-description" tabindex="-1">3. Feature Description <a class="header-anchor" href="#_3-feature-description" aria-label="Permalink to &quot;3. Feature Description&quot;">​</a></h2><h3 id="_1-definition-of-two-factor-authentication" tabindex="-1">(1) Definition of Two-Factor Authentication <a class="header-anchor" href="#_1-definition-of-two-factor-authentication" aria-label="Permalink to &quot;(1) Definition of Two-Factor Authentication&quot;">​</a></h3><p>Two-Factor Authentication (2FA) provides an additional layer of protection for user logins.</p><p>Once this feature is enabled and configured, users must provide more than just their username and password when logging in. They must also enter a verification code, such as:</p><ul><li>A security code</li><li>A time-based token</li><li>A dynamic code generated by an authentication app such as Google Authenticator or Duo</li></ul><p>This two-step verification method greatly increases the difficulty of unauthorized access and significantly improves account security.</p><h3 id="_2-enabling-the-feature" tabindex="-1">(2) Enabling the Feature <a class="header-anchor" href="#_2-enabling-the-feature" aria-label="Permalink to &quot;(2) Enabling the Feature&quot;">​</a></h3><p>Users can click the green “Click Here to Enable” button on the page and follow the system instructions to complete the setup process.</p><p>The configuration process typically includes:</p><ul><li>Linking an authentication app (such as Google Authenticator or Duo)</li><li>Generating and saving backup verification codes</li></ul><p>These backup codes can be used to log in if the user is temporarily unable to access their authentication app.</p><p>By enabling Two-Factor Authentication and following the relevant security recommendations, users can significantly improve the security of their platform accounts, effectively reduce the risk of account theft and information leakage, and provide stronger protection for account access and related operations.</p>',17)])])}const f=t(n,[["render",r]]);export{d as __pageData,f as default};
